const pays = $input.all().map(i => i.json).filter(r => r['Payment ID']);
const t = dayNum(todayStr);
const cur = cfg.currency || 'Rs';
let active = 0, expired = 0, newJoins = 0, expSoon = 0, pendingCount = 0, pendingAmount = 0;
for (const r of members) {
  const d = dayNum(r.Expiry) - t;
  if (r.Status === 'Expired' || d < 0) expired++; else active++;
  if (d >= 0 && d <= 7) expSoon++;
  const age = t - dayNum(r['Join Date']);
  if (age >= 0 && age < 7) newJoins++;
  if (r['Payment Status'] === 'Pending') { pendingCount++; pendingAmount += Number(r.Fee) || 0; }
}
const weekRevenue = pays.filter(p => { const a = t - dayNum(p.Date); return p.Status === 'Paid' && a >= 0 && a < 7; }).reduce((s, p) => s + (Number(p.Amount) || 0), 0);
const text = `📊 ${cfg.gymName} - Weekly Report (${todayStr})\nTotal members: ${members.length}\nActive: ${active} | Expired: ${expired}\nNaye members (7 din): ${newJoins}\nIs hafte expire hone wale: ${expSoon}\nIs hafte collection: ${cur} ${weekRevenue}\nPending payments: ${pendingCount} (${cur} ${pendingAmount})`;
const row = (a, b) => `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">${esc(a)}</td><td style="padding:6px 12px;border-bottom:1px solid #eee"><b>${esc(b)}</b></td></tr>`;
const html = `<div style="font-family:Arial,sans-serif"><h2>${esc(cfg.gymName)} - Weekly Report</h2><p>${esc(todayStr)}</p><table style="border-collapse:collapse">` +
  row('Total members', members.length) + row('Active', active) + row('Expired', expired) + row('New members (7 days)', newJoins) +
  row('Expiring this week', expSoon) + row('Collection this week', cur + ' ' + weekRevenue) + row('Pending payments', pendingCount + ' (' + cur + ' ' + pendingAmount + ')') + '</table></div>';
return [{ json: { name: 'Owner', type: 'Report', phone: norm(cfg.ownerPhone), message: text, ownerEmail: cfg.ownerEmail, subject: `${cfg.gymName} - Weekly Report (${todayStr})`, html } }];

