const sources = ['Build Welcome Message', 'Duplicate Message', 'Not Found Message', 'Build Renewal Message', 'Build Payment Message', 'Build Reminder Message', 'Build Weekly Report'];
return $input.all().map((it, i) => {
  let src = {};
  for (const s of sources) {
    try { const m = $(s).itemMatching(i); if (m && m.json && m.json.phone) { src = m.json; break; } } catch (e) {}
  }
  const e = it.json.error;
